import React, { useState } from "react";
import { getLanguagesFromApi } from "../api/netflixApi";

const NetflixLen = () => {
    const [languages, setLanguages] = useState([]);
    const [loading, setLoading] = useState(false);

    const handleFetch = async () => {
        setLoading(true);
        try {
            const res = await getLanguagesFromApi();
            setLanguages(res.data);
        } catch (error) {
            console.error("Error al obtener lenguajes:", error);
            alert("No se pudo obtener la lista de lenguajes");
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="mt-4">
            <h5>Lenguajes isponibles en Netflix</h5>
            {loading && <p>Cargando...</p>}
            <div className="table-responsive">
                <table className="table table-striped table-bordered">
                    <thead className="table-dark">
                        <tr>
                            <th>ID</th>
                            <th>Código</th>
                            <th>Nombre</th>
                        </tr>
                    </thead>
                    <tbody>
                        {languages.length > 0 ? (
                            languages.map((lang, i) => (
                                <tr key={i}>
                                    <td>{lang.id || i}</td>
                                    <td>{lang.code || ""}</td>
                                    <td>{lang.name || ""}</td>
                                </tr>
                            ))
                        ) : (
                            <tr>
                                <td colSpan="3" className="text-center">
                                    No hay lenguajes
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export default NetflixLen;
